package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.content.SharedPreferences;
import org.json.JSONObject;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
/** Serializes refreshes, preserving identity and never restoring a logged-out session. */
final class AuthSession {
 static synchronized String token(Context c)throws Exception{SharedPreferences p=SessionPreferences.get(c);String old=p.getString("access_token",""),user=p.getString("user_id","");if(old.isEmpty()||user.isEmpty())throw new IOException("Entre novamente.");if(p.getLong("expires_at",0)>System.currentTimeMillis()+60000)return old;String refresh=p.getString("refresh_token","");if(refresh.isEmpty())throw new IOException("Sua sessão expirou. Entre novamente.");String[] cfg=SupabaseAuthClient.loadConfig();HttpURLConnection conn=(HttpURLConnection)new URL(cfg[0]+"/auth/v1/token?grant_type=refresh_token").openConnection();try{conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(12000);conn.setReadTimeout(12000);conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("apikey",cfg[1]);conn.setRequestProperty("Content-Type","application/json");try(OutputStream out=conn.getOutputStream()){out.write(new JSONObject().put("refresh_token",refresh).toString().getBytes(StandardCharsets.UTF_8));}if(conn.getResponseCode()!=200)throw new IOException("Não foi possível renovar a sessão. Entre novamente.");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=conn.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>1024*1024)throw new IOException("Resposta inválida.");bytes.write(b,0,n);}}JSONObject session=new JSONObject(bytes.toString("UTF-8"));String next=session.optString("access_token"),rotated=session.optString("refresh_token");if(!old.equals(p.getString("access_token",""))||!user.equals(p.getString("user_id","")))throw new IOException("A sessão mudou.");JSONObject owner=session.optJSONObject("user");if(owner==null||!user.equals(owner.optString("id"))||next.isEmpty()||rotated.isEmpty())throw new IOException("Sessão inválida.");p.edit().putString("access_token",next).putString("refresh_token",rotated).putLong("expires_at",System.currentTimeMillis()+session.optLong("expires_in",3600)*1000).apply();return next;}finally{conn.disconnect();}}
}
